<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>同层微博</title>
<style>
html,body{margin:0;padding:0;background:transparent;font-family:-apple-system,"PingFang SC","Microsoft YaHei",sans-serif}
#boot{max-width:420px;height:640px;margin:0 auto;display:flex;align-items:center;justify-content:center;
