<body>
<div id="boot">
  <div>
    <div style="font-size:22px;margin-bottom:8px">🟠</div>
    <div id="tt">正在加载同层微博…</div>
    <div class="sub" id="sub">从远端拉取 UI</div>
    <div class="spin"></div>
  </div>
</div>
<script>
(function () {
  var HTML_URL = 'https://fchris1219-del.github.io/weibo-phone/weibo.html';
  var RETRY = 3;
  var TIMEOUT = 15000;
  var injection =
    "const charName='{{char}}';\n" +
    "        const userName = \"{{user}}\";\n" +
    "        const userAvatarPath =\"{{userAvatarPath}}\";\n" +
    "        const charAvatarPath = \"{{charAvatarPath}}\";\n" +
    "  window.charName = charName;\n" +
    "  window.userName = userName;\n" +
    "  window.userAvatarPath = userAvatarPath;\n" +
    "  window.charAvatarPath = charAvatarPath;\n";

  function setStatus(t, s) {
    var a = document.getElementById("tt");
    var b = document.getElementById("sub");
    if (a) a.textContent = t;
    if (b) b.textContent = s || "";
  }

  function showErr(msg) {
    var el = document.getElementById("boot");
    if (!el) return;
    el.innerHTML =
      '<div><div style="font-size:22px;margin-bottom:8px">❌</div><div>加载失败</div>' +
      '<div class="sub"></div><button type="button" id="retry">重试</button></div>';
    var sub = el.querySelector(".sub");
    if (sub) sub.textContent = String(msg || "");
    var btn = document.getElementById("retry");
    if (btn) btn.onclick = function () { location.reload(); };
  }

  function withTimeout(p, ms) {
    return new Promise(function (resolve, reject) {
      var to = setTimeout(function () { reject(new Error("超时 " + ms + "ms")); }, ms);
      p.then(
        function (v) { clearTimeout(to); resolve(v); },
        function (e) { clearTimeout(to); reject(e); }
      );
    });
  }

  async function fetchHtml() {
    var last = null;
    for (var i = 1; i <= RETRY; i++) {
      setStatus("正在拉取…", "第 " + i + "/" + RETRY + " 次\n" + HTML_URL);
      try {
        var url = HTML_URL + (HTML_URL.indexOf("?") >= 0 ? "&" : "?") + "t=" + Date.now();
        var res = await withTimeout(
          fetch(url, { cache: "no-store", mode: "cors", credentials: "omit" }),
          TIMEOUT
        );
        if (!res.ok) throw new Error("HTTP " + res.status);
        var text = await withTimeout(res.text(), TIMEOUT);
        if (!text || text.length < 200) throw new Error("内容过短 " + (text ? text.length : 0));
        return text;
      } catch (e) {
        last = e;
        await new Promise(function (r) { setTimeout(r, 700 * i); });
      }
    }
    throw last || new Error("fetch failed");
  }

  function injectAndRender(html) {
    var s = String(html || "");
    if (/<script>/i.test(s)) {
      s = s.replace(/<script>/i, "<script>\n" + injection + "\n");
    } else {
      // 结束标签必须拆开，防止本页源码被浏览器提前截断
      s = "<script>\n" + injection + "\n<" + "/script>\n" + s;
    }
    setStatus("注入界面…", "size " + s.length);
    try {
      document.open();
      document.write(s);
      document.close();
      return;
    } catch (e1) {
      console.warn("[同层微博] document.write 失败", e1);
    }
    try {
      var blob = new Blob([s], { type: "text/html;charset=utf-8" });
      location.replace(URL.createObjectURL(blob));
      return;
    } catch (e2) {
      console.warn("[同层微博] blob 失败", e2);
    }
    showErr("无法注入页面");
  }

  async function main() {
    try {
      if (!HTML_URL || HTML_URL.indexOf("example.com") >= 0) {
        showErr("未配置 HTML_URL");
        return;
      }
      var html = await fetchHtml();
      injectAndRender(html);
    } catch (e) {
      console.error("[同层微博]", e);
      showErr((e && e.message) ? e.message : String(e));
    }
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", main);
  else main();
})();
</script>
</body>
